import pytest
from login import login

@pytest.mark.parametrize("username,password", [
    ("demο", "demo-only"), ("dеmo", "demo-only"),
    ("demo", "demo‐only"), ("demo ", "demo-only"),
    ("demo", "demo-only\n"),
])
def test_confusable_and_whitespace_credentials_are_rejected(username, password):
    assert login(username, password) is False
